package com.smartproperty.platform.parking.service.impl;
import com.smartproperty.platform.access.*;import com.smartproperty.platform.auth.context.*;import com.smartproperty.platform.common.api.PageResult;import com.smartproperty.platform.common.exception.BusinessException;import com.smartproperty.platform.parking.dto.*;import com.smartproperty.platform.parking.mapper.ParkingPermitMapper;import com.smartproperty.platform.parking.mapper.ParkingPermitMapper.*;import com.smartproperty.platform.parking.query.ParkingPermitQuery;import com.smartproperty.platform.parking.service.ParkingPermitService;import com.smartproperty.platform.parking.vo.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class ParkingPermitServiceImpl implements ParkingPermitService {
 private static final BigDecimal FIRST_RATE=new BigDecimal("200.00"),SECOND_RATE=new BigDecimal("1200.00");private final ParkingPermitMapper mapper;private final AuthorizationService authorization;private final DataScopeService scope;private final ActorContextProvider actorProvider;
 public ParkingPermitServiceImpl(ParkingPermitMapper m,AuthorizationService a,DataScopeService s,ActorContextProvider p){mapper=m;authorization=a;scope=s;actorProvider=p;}
 @Override public ParkingPermitSummaryVO adminSummary(){authorization.requirePermission(PermissionCodes.PARKING_PERMIT_VIEW);var q=scoped(new ParkingPermitQuery());return new ParkingPermitSummaryVO(mapper.countPending(q),mapper.countActive(q),mapper.countExpiringSoon(q));}
 @Override public PageResult<ParkingPermitApplicationVO> pageApplications(ParkingPermitQuery q){authorization.requirePermission(PermissionCodes.PARKING_PERMIT_VIEW);normalize(q);scoped(q);long total=mapper.countApplications(q);return PageResult.of(mapper.selectApplicationPage(q,offset(q),q.getPageSize()),total,q.getPage(),q.getPageSize());}
 @Override public PageResult<ParkingPermitVO> pagePermits(ParkingPermitQuery q){authorization.requirePermission(PermissionCodes.PARKING_PERMIT_VIEW);normalize(q);scoped(q);long total=mapper.countPermits(q);return PageResult.of(mapper.selectPermitPage(q,offset(q),q.getPageSize()),total,q.getPage(),q.getPageSize());}
 @Override @Transactional public ParkingPermitApplicationVO review(Long id,ReviewParkingPermitApplicationRequest request){ActorContext actor=authorization.requirePermission(PermissionCodes.PARKING_PERMIT_MANAGE);ApplicationRow app=requireApplication(id);scope.requireProperty(app.propertyUnitId());String decision=request.decision().trim().toUpperCase(Locale.ROOT);if("REJECT".equals(decision)){String reason=blank(request.rejectionReason());if(reason==null)throw bad("REJECTION_REASON_REQUIRED","拒绝申请时请填写原因");if(mapper.rejectApplication(id,actor.accountId(),reason)!=1)throw conflict("APPLICATION_STATE_CHANGED","申请状态已变化，请刷新后重试");return mapper.selectApplication(id);}if(!"APPROVE".equals(decision))throw bad("INVALID_REVIEW_DECISION","审核操作必须为 APPROVE 或 REJECT");mapper.lockPerson(app.personId());mapper.lockProperty(app.propertyUnitId());verifyEligibility(app.personId(),app.propertyUnitId(),app.residenceId(),app.source());Quote quote=quote(app.personId(),app.propertyUnitId(),app.months());if(mapper.approveApplication(id,actor.accountId(),quote.sequence(),quote.rate(),quote.total())!=1)throw conflict("APPLICATION_STATE_CHANGED","申请状态已变化，请刷新后重试");LocalDate to=validTo(app.requestedValidFrom(),app.months());PermitCommand permit=new PermitCommand("PP-"+String.format("%08d",id),app,quote.sequence(),quote.rate(),quote.total(),to);mapper.insertPermit(permit);return mapper.selectApplication(id);}
 @Override public List<ParkingEligibilityVO> myEligibilities(){return mapper.selectEligibilities(currentPerson());}@Override public List<VehicleVO> myVehicles(){return mapper.selectVehicles(currentPerson());}
 @Override @Transactional public VehicleVO createMyVehicle(CreateVehicleRequest r){Long person=currentPerson();String plate=normalizePlate(r.plateNumber());try{VehicleCommand command=new VehicleCommand(person,plate,vehicleType(r.vehicleType()),blank(r.brand()),blank(r.color()));mapper.insertVehicle(command);return mapper.selectVehicles(person).stream().filter(v->v.vehicleId().equals(command.getVehicleId())).findFirst().orElseThrow();}catch(DataIntegrityViolationException e){throw conflict("VEHICLE_PLATE_EXISTS","该车牌已被登记");}}
 @Override public List<ParkingPermitApplicationVO> myApplications(){return mapper.selectMyApplications(currentPerson());}@Override public List<ParkingPermitVO> myPermits(){return mapper.selectMyPermits(currentPerson());}
 @Override @Transactional public ParkingPermitApplicationVO submitMyApplication(SubmitParkingPermitApplicationRequest r){Long person=currentPerson();if(!mapper.existsVehicleOwned(r.vehicleId(),person))throw forbidden("VEHICLE_NOT_OWNED","只能使用本人名下的有效车辆申请车证");EligibilityRow eligibility=verifyEligibility(person,r.propertyUnitId(),null,null);if(mapper.existsPendingApplication(person,r.vehicleId(),r.propertyUnitId()))throw conflict("PARKING_PERMIT_APPLICATION_PENDING","该车辆在此房产已有待审核申请");LocalDate from=LocalDate.now();LocalDate to=validTo(from,r.requestedMonths());if("RESIDENCE".equals(eligibility.source())&&eligibility.expectedEndDate()!=null&&to.isAfter(eligibility.expectedEndDate()))throw bad("PERMIT_EXCEEDS_RESIDENCE_TERM","租赁车证有效期不能超过当前租住约定期限");Quote quote=quote(person,r.propertyUnitId(),r.requestedMonths());ApplicationCommand command=new ApplicationCommand("PPA-"+UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase(Locale.ROOT),person,r.vehicleId(),r.propertyUnitId(),eligibility.residenceId(),eligibility.source(),r.requestedMonths(),from,quote.sequence(),quote.rate(),quote.total());mapper.insertApplication(command);return mapper.selectApplication(command.getApplicationId());}
 private <T extends ParkingPermitQuery>T scoped(T q){return scope.apply(q);}private long offset(ParkingPermitQuery q){return (long)(q.getPage()-1)*q.getPageSize();}private void normalize(ParkingPermitQuery q){if(q.getPage()==null||q.getPage()<1)q.setPage(1);if(q.getPageSize()==null||q.getPageSize()<1)q.setPageSize(20);if(q.getPageSize()>100)q.setPageSize(100);if(q.getKeyword()!=null)q.setKeyword(q.getKeyword().trim());}
 private ApplicationRow requireApplication(Long id){ApplicationRow row=mapper.selectApplicationRow(id);if(row==null)throw new BusinessException(HttpStatus.NOT_FOUND,"PARKING_PERMIT_APPLICATION_NOT_FOUND","未找到车证申请");if(!"PENDING".equals(row.status()))throw conflict("APPLICATION_STATE_CHANGED","该申请已经完成审核");return row;}
 private EligibilityRow verifyEligibility(Long person,Long property,Long expectedResidence,String expectedSource){EligibilityRow result=mapper.selectEligibleSource(person,property);if(result==null)throw forbidden("PARKING_ELIGIBILITY_REQUIRED","当前房产权益不具备车证申请资格");if(expectedResidence!=null&&!Objects.equals(expectedResidence,result.residenceId()))throw conflict("PARKING_ELIGIBILITY_CHANGED","租赁停车资格已变化，不能继续审核");if(expectedSource!=null&&!expectedSource.equals(result.source()))throw conflict("PARKING_ELIGIBILITY_CHANGED","停车资格来源已变化，不能继续审核");return result;}
 private Quote quote(Long person,Long property,int months){if(mapper.countActivePermitsForPerson(person)>=2)throw conflict("PERSON_PERMIT_LIMIT","同一人员同时有效车证最多两张");int active=mapper.countActivePermitsForProperty(property);if(active>=2)throw conflict("PROPERTY_PERMIT_LIMIT","该房产当前没有可用车证申请名额");int sequence=active+1;BigDecimal rate=sequence==1?FIRST_RATE:SECOND_RATE;return new Quote(sequence,rate,rate.multiply(BigDecimal.valueOf(months)));}private LocalDate validTo(LocalDate from,int months){return from.plusMonths(months).minusDays(1);}private Long currentPerson(){ActorContext actor=actorProvider.currentActor();if(!actor.hasRole("PERSON_USER")||actor.personId()==null)throw forbidden("RESIDENT_IDENTITY_REQUIRED","当前接口仅供已绑定居民身份的账号使用");return actor.personId();}private String normalizePlate(String value){return value==null?"":value.trim().replaceAll("\\s+","").toUpperCase(Locale.ROOT);}private String vehicleType(String value){String type=blank(value);return Set.of("CAR","MOTORCYCLE","NEW_ENERGY").contains(type)?type:"CAR";}private String blank(String v){return v==null||v.isBlank()?null:v.trim();}private BusinessException bad(String c,String m){return new BusinessException(HttpStatus.BAD_REQUEST,c,m);}private BusinessException forbidden(String c,String m){return new BusinessException(HttpStatus.FORBIDDEN,c,m);}private BusinessException conflict(String c,String m){return new BusinessException(HttpStatus.CONFLICT,c,m);}private record Quote(int sequence,BigDecimal rate,BigDecimal total){}
}
